import {commandHtml,commandClick,commandChange} from './farm-command-ui.js';
import {SPECIALTIES,FARM_EVENTS} from './farm-systems.js';
import {HOMESTEAD} from './homestead.js';
import {createHousePanel,installHouseHotspots} from './house-ui.js';
import {ColonyEngine} from './colony.js';
import {JOBS,TOOLS,BUILDINGS,GADGETS} from './engine.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const slotName=s=>s==='auto'?'Latest autosave':s==='previous'?'Previous autosave':'Farm '+s.slice(-1);
const costLabel=cost=>Object.entries(cost).map(([resource,amount])=>amount+' '+(resource==='pantry'?'preserved rations':resource)).join(' + ');
const count=n=>Math.max(0,Math.floor(n||0));
const stock=(label,value,detail,capacity)=>'<div class="homestead-stock"><span>'+esc(label)+'</span><strong>'+count(value)+(capacity===undefined?'':' <small>/ '+count(capacity)+'</small>')+'</strong><small>'+esc(detail)+'</small></div>';

export function installFarmManagement({saveWhere='browser',game,store,load,selected,notice,sync,focusGame}){
 const $=id=>document.getElementById(id);let page='people',resumeAfter=false,personId=null;
 const button=document.createElement('button');button.type='button';button.id='farm-life-btn';button.className='cmd';button.innerHTML='<svg class="icon"><use href="#i-anvil"/></svg><span>Farm command</span>';button.setAttribute('aria-label','Farm command center');button.title='Survivor priorities, construction queue and defense coordination';$('ops-btn').after(button);
 const dialog=document.createElement('dialog');dialog.id='farm-management';dialog.className='help-dialog management-dialog';dialog.setAttribute('aria-labelledby','management-title');dialog.innerHTML='<div class="help-modal"><header class="management-head"><h2 id="management-title">Farm life</h2><button id="management-close" type="button" class="icon-button" aria-label="Close farm management">×</button></header><nav class="management-tabs" aria-label="Farm management"><button type="button" data-page="house">House</button><button type="button" data-page="kitchen">Kitchen</button><button type="button" data-page="animals">Animals</button><button type="button" data-page="people">Survivors</button><button type="button" data-page="events">Events</button><button type="button" data-page="command">Command</button><button type="button" data-page="construction">Construction</button><button type="button" data-page="saves">Saves</button></nav><div id="management-content"></div><p id="management-message" role="status" aria-live="polite"></p><footer class="management-foot"><button id="management-plan" class="primary-button" type="button" hidden>Plan the day →</button></footer></div>';document.body.append(dialog);
 const message=text=>$('management-message').textContent=text;
 const housePanel=createHousePanel({game,dialog,render,message,sync});
 const houseButton=document.createElement('button');houseButton.type='button';houseButton.id='house-rooms';houseButton.className='house-open-button';houseButton.textContent='House & rooms →';document.querySelector('.house-heading').append(houseButton);houseButton.addEventListener('click',()=>{open('house');housePanel.focus('overview');});
 installHouseHotspots({open:(tab,key)=>{if(game.s.mode!=='house')return;open('house');housePanel.focus(tab,key);}});
 const intro=(eyebrow,title,text)=>'<div class="homestead-intro"><div><p class="eyebrow">'+esc(eyebrow)+'</p><h3>'+esc(title)+'</h3><p>'+esc(text)+'</p></div><span class="homestead-day">DAY '+game.s.day+'</span></div>';
 const stores=h=>'<div class="homestead-stores" aria-label="Available supplies">'+['food','water','scrap','hay'].map(k=>'<span>'+esc(k)+' <strong>'+count(h[k])+'</strong></span>').join('')+'</div>';
 function actionCard(id,action,title,description,yieldText){const reason=action.reason||(action.available?'Ready to prepare.':'Not available right now.');return '<article class="homestead-card"><h4>'+esc(title)+'</h4><p>'+esc(description)+'</p><p class="homestead-yield">'+esc(yieldText)+'</p><p class="homestead-cost">Costs '+esc(costLabel(action.cost))+'</p><button type="button" data-homestead-action="'+id+'" aria-describedby="homestead-'+id+'-reason" '+(!action.available?'disabled':'')+'>'+esc(action.label)+'</button><p id="homestead-'+id+'-reason" class="homestead-reason'+(!action.available?' is-blocked':'')+'">'+esc(reason)+'</p></article>';}
 function renderKitchen(){const h=game.homesteadStatus();return intro('THE FARMHOUSE KITCHEN','Keep the table full.','Cook tomorrow’s breakfast or put a few rations aside for a difficult day.')+'<div class="homestead-stocks">'+stock('Prepared meals',h.meals,'Used first at breakfast',h.mealCap)+stock('Preserved rations',h.pantry,'Open jars to use as food',h.pantryCap)+stock('Food in storage',h.food,'Harvests, milk and supplies',game.s.foodCap)+stock('Water in storage',h.water,'For cooking and drinking',game.s.waterCap)+'</div>'+stores(h)+'<div class="homestead-recipes">'+actionCard('cook',h.actions.cook,'Cook a warm breakfast','Prepared portions replace food at the next breakfast. Each fed survivor who gets one gains '+HOMESTEAD.mealMorale+' morale.',h.actions.cook.yield+' PREPARED PORTIONS')+actionCard('preserve',h.actions.preserve,'Fill the pantry','Pack spare food into a separate reserve. Preserved rations stay in the pantry until you open them.',h.actions.preserve.yield+' PRESERVED RATIONS')+actionCard('open',h.actions.open,'Open a batch of rations','Move preserved rations back into food storage for the farm or a scouting party.',h.actions.open.yield+' FOOD FOR THE FARM')+'</div><p class="homestead-footnote">Breakfast still needs drinking water. Teo needs an extra helping. Scouting teams pack food from storage, so open pantry rations before sending a team.</p>';}
 function renderAnimals(){const h=game.homesteadStatus(),b=h.breeding,remaining=b?Math.max(0,b.daysLeft):0,progress=b?Math.max(0,Math.min(HOMESTEAD.breedDays,HOMESTEAD.breedDays-remaining)):0;
  const pregnancy=b?'<div class="homestead-progress"><label for="calf-progress">'+(b.ready?'Calf ready · waiting for a free place':'Calf expected on day '+b.dueDay+' · '+remaining+' dawn'+(remaining===1?'':'s')+' to go')+'</label><progress id="calf-progress" value="'+progress+'" max="'+HOMESTEAD.breedDays+'"></progress></div>':'<p>No calf is expected yet. One breeding can be underway at a time.</p>';
  return intro('PASTURE & BARN','Grow the herd.','Healthy cows and a little saved feed can bring a new calf to the farm.')+'<div class="homestead-stocks">'+stock('Cows',h.cows,'Including cows sheltered in the barn',h.cowCapacity)+stock('Healthy parents',h.healthyCows,'At least '+Math.round(HOMESTEAD.healthyRatio*100)+'% health')+stock('Hay saved',h.hay,'Harvested crops supply the barn')+stock('Nursery places',h.nurseryCapacity,h.nurseryCapacity?'One extra place from the upgraded barn':'Upgrade the barn for a nursery')+'</div>'+stores(h)+'<p class="pop-note">'+h.normalCowCapacity+' regular cattle place'+(h.normalCowCapacity===1?'':'s')+' + '+h.nurseryCapacity+' nursery place'+(h.nurseryCapacity===1?'':'s')+'. A calf needs a free place when it arrives.</p><div class="homestead-herd"><article class="homestead-card"><h4>'+(b?'A calf on the way':'Plan a new calf')+'</h4>'+pregnancy+'<p>Breeding needs two healthy cows, feed and a free cattle place. A calf arrives after '+HOMESTEAD.breedDays+' dawns.</p><p class="homestead-cost">Costs '+esc(costLabel(h.actions.breed.cost))+'</p><button type="button" data-homestead-action="breed" aria-describedby="homestead-breed-reason" '+(!h.actions.breed.available?'disabled':'')+'>'+esc(h.actions.breed.label)+'</button><p id="homestead-breed-reason" class="homestead-reason'+(!h.actions.breed.available?' is-blocked':'')+'">'+esc(h.actions.breed.reason||'Ready to start breeding.')+'</p></article><section class="homestead-cows" aria-labelledby="herd-title"><h4 id="herd-title">Your herd</h4>'+(game.s.cows.length?'<ul>'+game.s.cows.map((cow,i)=>'<li><span>'+esc(cow.name||'Cow '+(i+1))+'<small>'+esc(cow.inside?'Sheltered in the barn':'Out in the pasture')+' · '+(cow.hp/cow.maxHp>=HOMESTEAD.healthyRatio?'healthy enough to breed':'needs time to recover')+'</small></span><span class="cow-health">'+Math.ceil(cow.hp)+' / '+cow.maxHp+' HP</span></li>').join('')+'</ul>':'<p class="pop-note">Build a pasture to bring the first cows to your farm.</p>')+'</section></div>';
 }
 function renderBonds(p){const bonds=game.homesteadStatus().relationships.filter(b=>b.a===p.id||b.b===p.id);return '<section class="survivor-bonds" aria-labelledby="survivor-bonds-title"><h4 id="survivor-bonds-title">Life together</h4><p class="pop-note">Shared breakfasts and completed expeditions build trust. Close company adds up to '+HOMESTEAD.bondMoraleCap+' morale.</p>'+(bonds.length?'<ul>'+bonds.map(b=>{const other=b.a===p.id?b.names[1]:b.names[0];return '<li><strong>'+esc(other)+'</strong><span>'+esc(b.label)+' <meter min="0" max="10" value="'+b.score+'" aria-label="Trust with '+esc(other)+'"></meter><span class="bond-score">'+Math.round(b.score)+'/10</span></span></li>';}).join('')+'</ul>':'<p class="pop-note">Bonds will grow as this survivor spends time with the others.</p>')+'</section>';}
 function render(){const s=game.s,active=['playing','paused','house'].includes(s.mode),morning=s.mode==='house';if(!morning&&['house','kitchen','animals','people','events'].includes(page))page='construction';dialog.querySelectorAll('[data-page]').forEach(b=>{b.hidden=!morning&&['house','kitchen','animals','people','events'].includes(b.dataset.page);});$('management-plan').hidden=!morning;$('management-title').textContent=page==='saves'?'Saved farms':morning?'Farm life':'Construction';dialog.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-pressed',String(b.dataset.page===page));});
  if(page==='command'){
   $('management-title').textContent='Farm command';$('management-content').innerHTML=commandHtml(game);
  }else if(page==='house'){
   $('management-content').innerHTML=housePanel.html();
  }else if(page==='kitchen'){
   $('management-content').innerHTML=renderKitchen();
  }else if(page==='animals'){
   $('management-content').innerHTML=renderAnimals();
  }else if(page==='people'){
   const p=s.people.find(p=>p.id===personId)||s.people.find(p=>selected.has(p.id))||s.people[0];personId=p?.id;
   $('management-content').innerHTML='<div class="survivor-tabs">'+s.people.map(p=>'<button type="button" data-person-profile="'+p.id+'" class="'+(p.id===personId?'active':'')+'">'+esc(p.name)+'</button>').join('')+'</div>'+(p?'<article class="survivor-profile"><h3>'+esc(p.name)+' · '+esc(p.specialty?SPECIALTIES[p.specialty]:'No specialization yet')+'</h3><p>'+esc(p.traits.good)+' / '+esc(p.traits.weak)+'</p><div class="profile-stats"><span>Health <strong>'+Math.ceil(p.hp)+' / '+p.maxHp+'</strong></span><span>Morale <strong>'+Math.round(p.morale)+' / 100</strong></span><span>Job <strong>'+esc(JOBS[p.job])+'</strong></span><span>Equipment <strong>'+esc(TOOLS[p.tool]||'None')+'</strong></span></div><p>'+esc(p.hp<p.maxHp*.4?'Badly wounded · treatment recommended':p.hp<p.maxHp?'Recovering from injuries':'Healthy')+' · '+esc(p.status)+'</p><p class="pop-note">Choose one permanent specialization after reaching skill level 2. Work specializations improve that work by 20%; Sharpshooter adds 20% damage; Pathfinder searches 30% faster on expeditions.</p><div class="skill-list">'+Object.entries(SPECIALTIES).map(([skill,label])=>'<div><strong>'+esc(label)+'</strong><span>Level '+game.skill(p,skill)+'/5 · '+Math.floor(p.skills[skill])+' XP · '+Math.floor(p.workHistory[skill]||0)+' XP earned since tracking began</span><button type="button" data-specialize="'+skill+'" '+(!active||p.specialty||game.skill(p,skill)<2?'disabled':'')+'>'+(p.specialty===skill?'Chosen':p.specialty?'Locked':'Specialize')+'</button></div>').join('')+'</div><h4>Recent work</h4><ul>'+p.workLog.slice().reverse().map(e=>'<li>Day '+e.day+' · '+esc(e.text)+'</li>').join('')+'</ul></article>':'<p>No survivors.</p>');
   if(p)$('management-content').querySelector('.survivor-profile').insertAdjacentHTML('beforeend',renderBonds(p));
  }else if(page==='events'){
   const event=s.farmEvent,spec=FARM_EVENTS[event?.type];$('management-content').innerHTML=spec?'<article class="farm-event"><p class="eyebrow">DAY '+event.day+'</p><h3>'+esc(spec.title)+'</h3><p>'+esc(spec.text)+'</p><div class="event-choices">'+spec.choices.map(c=>'<button type="button" data-event-choice="'+c.id+'" '+(!active||!game.eventChoiceAvailable(c)?'disabled':'')+'>'+esc(c.label)+'</button>').join('')+'</div><p class="pop-note">Trades need room in storage. Welcoming a survivor needs a free bed. Only one expedition cache bonus can be marked at a time.</p></article>':'<p>All quiet for now. A new opportunity appears each day from day 2.</p>';
   $('management-content').innerHTML+='<h3>Farm history</h3><ul>'+s.eventHistory.slice(-12).reverse().map(e=>'<li>Day '+e.day+' · '+esc(FARM_EVENTS[e.type]?.title||e.type)+' · '+esc(FARM_EVENTS[e.type]?.choices.find(c=>c.id===e.choice)?.label||e.choice)+'</li>').join('')+'</ul>'+(s.expeditionBonus?'<p class="pop-note">Marked expedition cache: +'+s.expeditionBonus.scrap+' scrap, +'+Math.round(s.expeditionBonus.risk*100)+'% injury risk'+(s.expeditionBonus.place?' · abandoned farm only':'')+'.</p>':'');
  }else if(page==='construction'){
   $('management-content').innerHTML=housePanel.project()+'<p class="pop-note">Builders finish priority jobs first. Cancelling refunds the unused fraction of scrap; an aerial component is returned.</p><div class="construction-list">'+s.sites.map(site=>{const name=site.kind==='building'?BUILDINGS[site.building].name:GADGETS[site.gadget].name;return '<article><strong>'+esc(name)+(site.priority?' · PRIORITY':'')+'</strong><span>'+Math.round(site.progress*100)+'% complete</span><button type="button" data-priority="'+site.id+'">'+(site.priority?'Normal priority':'Build first')+'</button><button type="button" data-cancel-site="'+site.id+'">Cancel</button></article>';}).join('')+'</div>'+(!s.sites.length&&!s.house.project?'<p>No construction queued. Order buildings in Build, or drag on the map while placing fences.</p>':'');
  }else{
   $('management-content').innerHTML='<p class="pop-note">Three manual slots and two autosaves. '+(saveWhere==='folder'?'They are files in the game folder, in <strong>saves/</strong>, which GitHub ignores. Copy that folder to keep a backup.':'They stay in this browser, because the game was not opened through its own server. Export a file to keep a backup.')+' Loaded farms open paused.</p><div class="save-slots">'+store.entries().map(e=>'<article><div><strong>'+slotName(e.slot)+'</strong><small>'+ (e.day?'Day '+e.day+' · '+e.mode+' · '+esc(new Date(e.time).toLocaleString()):'Empty')+'</small></div>'+(e.slot.startsWith('manual')?'<button type="button" data-save-slot="'+e.slot+'" '+(!active?'disabled':'')+'>'+(e.raw?'Replace':'Save')+'</button>':'')+'<button type="button" data-load-slot="'+e.slot+'" '+(!e.raw?'disabled':'')+'>Load</button><button type="button" data-export-slot="'+e.slot+'" '+(!e.raw?'disabled':'')+'>Export</button></article>').join('')+'</div><div class="save-import"><label>Import farm file <input id="farm-import" type="file" accept=".json,application/json"></label><button type="button" id="export-current" '+(!active?'disabled':'')+'>Export current farm</button></div><p class="pop-note">Import validates the file, loads it paused and keeps it in Farm 3. Export Farm 3 first if you want to keep its existing contents.</p>';
  }
 }
 function open(next='people'){if(dialog.open){page=next;render();return;}if(document.querySelector('dialog[open]'))return;page=next;resumeAfter=game.s.mode==='playing';if(resumeAfter)game.pause();render();message('');dialog.showModal();}
 button.addEventListener('click',()=>open('command'));
 // Breakfast leads into Farm life; its last step is planning the day.
 $('house-farm-life').addEventListener('click',()=>open(game.s.farmEvent?'events':'kitchen'));
 $('management-plan').addEventListener('click',()=>{dialog.close();$('house-start').click();});$('management-close').addEventListener('click',()=>dialog.close());
 dialog.addEventListener('close',()=>{if(resumeAfter&&game.s.mode==='paused'&&!document.querySelector('dialog[open]'))game.resume();resumeAfter=false;sync();focusGame();});
 function exportRaw(raw){const blob=new Blob([raw],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='last-harvest-day-'+(JSON.parse(raw).s.day)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;try{
  if(commandClick(game,b)){render();sync();return;}
  if(housePanel.handleClick(e))return;
  if(b.hasAttribute('data-house-original-kitchen')){page='kitchen';render();return;}
  if(b.dataset.page){page=b.dataset.page;message('');render();}
  if(b.dataset.personProfile){personId=Number(b.dataset.personProfile);render();}
  if(b.dataset.homesteadAction){const methods={cook:'cookMeal',preserve:'preserveFood',open:'openPantry',breed:'breedCows'},action=b.dataset.homesteadAction,result=game[methods[action]]();render();message(result.message);const next=dialog.querySelector('[data-homestead-action="'+action+'"]');if(next&&!next.disabled)next.focus();else dialog.querySelector('[data-page="'+page+'"]').focus();}
  if(b.dataset.specialize){game.specialize(personId,b.dataset.specialize);render();}
  if(b.dataset.eventChoice){game.resolveFarmEvent(b.dataset.eventChoice);render();}
  if(b.dataset.priority){game.prioritizeSite(Number(b.dataset.priority));render();}
  if(b.dataset.cancelSite){game.cancelConstruction(Number(b.dataset.cancelSite));render();}
  if(b.dataset.saveSlot){store.write(game.serialize(),b.dataset.saveSlot);render();message('Saved to '+slotName(b.dataset.saveSlot)+'.');}
  if(b.dataset.loadSlot){const raw=store.read(b.dataset.loadSlot);resumeAfter=false;load(raw);}
  if(b.dataset.exportSlot)exportRaw(store.read(b.dataset.exportSlot));
  if(b.id==='export-current')exportRaw(game.serialize());
 }catch{message('Could not complete this action. Browser storage may be full or unavailable.');}sync();});
 dialog.addEventListener('change',async e=>{if(commandChange(game,e)){const key=['commandPolicy','guardPost','workEnable','workRank'].find(k=>e.target.dataset[k]),value=e.target.dataset[key],rank=e.target.dataset.rank;render();if(key){const attr='data-'+key.replace(/[A-Z]/g,c=>'-'+c.toLowerCase());dialog.querySelector('['+attr+'="'+value+'"]'+(rank!==undefined?'[data-rank="'+rank+'"]':''))?.focus();}sync();return;}housePanel.handleChange(e);if(e.target.id!=='farm-import')return;const file=e.target.files[0];if(!file)return;try{if(file.size>5_000_000)throw new Error('This file is too large to be a farm save.');const raw=await file.text(),probe=new ColonyEngine(),result=probe.restore(raw);if(result.error)throw new Error(result.error);store.write(raw,'manual-3');resumeAfter=false;load(raw);notice('Imported farm loaded paused and saved to Farm 3.');}catch(error){message(error.message||'The save could not be imported.');e.target.value='';}});
 // A small persistent indicator makes pending choices discoverable without interrupting a fight.
 let previous='';setInterval(()=>{const label=game.s.farmEvent?'kitchen · animals · people · 1 new event':'kitchen · animals · people';if(label!==previous){previous=label;$('house-farm-life').querySelector('small').textContent=label;$('house-farm-life').classList.toggle('event-ready',!!game.s.farmEvent);}},500);
 return {open};
}
